			"index": 0, "id": "call_x", "type": "function",
			"function": map[string]any{"name": "bash", "arguments": `{"command":"ls"}`},
		}}}, "tool_calls", nil)))
		_, _ = fmt.Fprint(w, "data: [DONE]\n\n")
