			Description: "Edit a file",
			Parameters:  json.RawMessage(`{"type":"object","required":["path"]}`),
		}},
		MaxTokens: 512,
	})
	if err != nil {
		t.Fatalf("Chat: %v", err)
	}
	// consume so the server finishes
	s, _ := p.Chat(context.Background(), auth.Credential{Key: ""}, protocol.ChatRequest{
		Model:    protocol.Model{ID: "model-42"},
		Messages: []protocol.Message{protocol.NewUserMessage("u1", "", "please")},
